CREATE TEMP TABLE sales_number_checks(name text,passed boolean);
CREATE FUNCTION pg_temp.assert(v boolean,n text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',n;END IF;INSERT INTO sales_number_checks VALUES(n,true);END$$;
DO $$DECLARE c uuid;actor uuid;other_c uuid;shared_id uuid:=gen_random_uuid();legacy_id uuid:=gen_random_uuid();q2 uuid:=gen_random_uuid();q3 uuid:=gen_random_uuid();customer uuid:=gen_random_uuid();p jsonb;cp jsonb;r jsonb;s jsonb;legacy jsonb;cfg jsonb;req uuid:=gen_random_uuid();n bigint;rev integer;denied boolean;branch uuid:=gen_random_uuid();branch2 uuid:=gen_random_uuid();BEGIN
 SELECT x.id,x.owner_user_id INTO c,actor FROM public.cafes x JOIN public.profiles p ON p.id=x.owner_user_id AND p.status='active' WHERE x.status='active' AND x.deleted_at IS NULL AND EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=x.id) ORDER BY x.created_at LIMIT 1;
 SELECT id INTO other_c FROM public.cafes WHERE id<>c AND owner_user_id<>actor AND deleted_at IS NULL ORDER BY id LIMIT 1;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);PERFORM set_config('sales.test.cafe',c::text,true);PERFORM set_config('sales.test.actor',actor::text,true);
 DELETE FROM public.erp_branch_scopes WHERE cafe_id=c AND user_id=actor;
 INSERT INTO public.bf_parties(id,cafe_id,kind,name,details) VALUES(customer,c,'customer','ERP-SALES-NUMBER-PROBE Customer','{"customerType":"individual"}');
 p:=jsonb_build_object('date',current_date,'validUntil','','status','draft','document',jsonb_build_object('template','standard','deliveryMethod','print','supplyDate',current_date,'extraFields','[]'::jsonb,'invoice',jsonb_build_object('warehouseId','','partyId',customer,'accountId','','paymentKind','credit','note','ERP-SALES-NUMBER-PROBE Quote','taxInclusive',false,'vatRate',0,'discountKind','amount','discountValue',0,'discountEnabled',false,'lines','[{"key":1,"productId":"","quantity":1,"price":20}]'::jsonb)));
 cp:=jsonb_build_object('template','standard','deliveryMethod','print','partyId',customer,'warehouseId','','sourceInvoiceId',NULL,'salespersonId',NULL,'date',current_date,'issueDate',current_date,'taxInclusive',false,'stockRequired',false,'discountKind','amount','discountValue',0,'vatRate',0,'reason','ERP-SALES-NUMBER-PROBE Credit','note','','terms','','lines','[{"key":1,"productId":"","quantity":1,"price":20}]'::jsonb);
 legacy:=public.brand_finance_save_quote(c,legacy_id,0,p);PERFORM pg_temp.assert(NOT legacy?'displayNumber','unconfigured source preserves original output');
 cfg:='{"context":"sales_quote","revision":0,"next":7,"padding":3,"mode":"numeric","prefix":"Q-","reset":"continue","unique":true}';r:=public.erp_system_numbering(c,'save',cfg,req);
 PERFORM pg_temp.assert(public.erp_system_numbering(c,'save',cfg,req)=r,'settings retry preserves response');
 PERFORM public.erp_system_numbering(c,'save','{"context":"sales_credit_note","revision":0,"next":7,"padding":3,"mode":"numeric","prefix":"CN-","reset":"continue","unique":true}',gen_random_uuid());
 r:=public.brand_finance_save_quote(c,shared_id,0,p);n:=(r->>'number')::bigint;rev:=(r->>'revision')::integer;
 PERFORM pg_temp.assert(r->>'displayNumber'='Q-007','actual quote save returns allocated display number');
 PERFORM pg_temp.assert((SELECT number=n FROM public.bf_quotes WHERE id=shared_id),'quote numeric identity unchanged');
 PERFORM pg_temp.assert(public.brand_finance_save_quote(c,shared_id,0,p)=r,'actual quote retry preserves identity and display');
 PERFORM pg_temp.assert((public.brand_finance_quotes(c,shared_id)->>'displayNumber')='Q-007','actual quote detail returns display');
 PERFORM pg_temp.assert(EXISTS(SELECT 1 FROM jsonb_array_elements(public.brand_finance_quotes(c))x WHERE x->>'id'=shared_id::text AND x->>'displayNumber'='Q-007'),'actual quote list returns display');
 PERFORM pg_temp.assert(EXISTS(SELECT 1 FROM jsonb_array_elements(public.brand_finance_customer_detail(c,customer,'quotes',1)->'quotes')x WHERE x->>'id'=shared_id::text AND x->>'displayNumber'='Q-007'),'customer linked quote reader uses display');
 PERFORM pg_temp.assert(NOT(public.brand_finance_quotes(c,legacy_id)?'displayNumber'),'existing record never retroactively renumbered');
 r:=public.brand_finance_save_quote(c,shared_id,rev,jsonb_set(p,'{validUntil}',to_jsonb((current_date+2)::text)));PERFORM pg_temp.assert(r->>'displayNumber'='Q-007' AND(r->>'number')::bigint=n,'quote editing preserves both numbers');
 s:=public.brand_finance_save_credit_note(c,shared_id,0,cp);PERFORM pg_temp.assert(s->>'displayNumber'='CN-007','same UUID different source has own display context');
 PERFORM pg_temp.assert(public.brand_finance_save_credit_note(c,shared_id,0,cp)=s,'credit-note retry preserves allocated display');
 PERFORM pg_temp.assert(public.brand_finance_credit_notes(c,shared_id)->>'displayNumber'='CN-007','actual credit-note detail display');
 r:=public.brand_finance_credit_notes(c,NULL,'{"query":"CN-007","limit":1,"offset":0}');PERFORM pg_temp.assert((r->>'total')::integer=1 AND r#>>'{items,0,displayNumber}'='CN-007','credit search matches display before pagination/count');
 PERFORM pg_temp.assert((public.brand_finance_credit_notes(c,NULL,'{"query":"Q-007"}')->>'total')::integer=0,'quote display cannot leak through credit search');
 PERFORM pg_temp.assert(erp_work_private.target(c,'quotation',shared_id)->>'label'='عرض سعر #Q-007','linked workflow quote label');
 PERFORM pg_temp.assert(erp_work_private.target(c,'credit_note',shared_id)->>'label'='إشعار دائن #CN-007','linked work-order credit label');
 PERFORM pg_temp.assert(EXISTS(SELECT 1 FROM jsonb_array_elements(public.erp_work_order_targets(c,'quotation','Q-007'))x WHERE x->>'id'=shared_id::text AND x->>'displayNumber'='Q-007'),'actual work-order quote search uses display');
 PERFORM pg_temp.assert(EXISTS(SELECT 1 FROM jsonb_array_elements(public.erp_work_order_targets(c,'credit_note','CN-007'))x WHERE x->>'id'=shared_id::text AND x->>'displayNumber'='CN-007'),'actual work-order credit search uses display');
 PERFORM pg_temp.assert(NOT(erp_settings_private.display_record(other_c,jsonb_build_object('id',shared_id),ARRAY['sales_quote'])?'displayNumber'),'registry tenant boundary');
 SELECT revision INTO rev FROM public.erp_system_numbering WHERE cafe_id=c AND context='sales_quote';
 PERFORM public.erp_system_numbering(c,'save',jsonb_set(cfg,'{revision}',to_jsonb(rev)),gen_random_uuid());r:=public.brand_finance_save_quote(c,q2,0,p);PERFORM pg_temp.assert(r->>'displayNumber'='Q-008','reset next skips existing display collision');
 r:=public.brand_finance_save_quote(c,q3,0,p);PERFORM pg_temp.assert(r->>'displayNumber'='Q-009','independent requests allocate next unique display');
 INSERT INTO public.branches(id,cafe_id,name,active) VALUES(branch,c,'ERP-SALES-NUMBER-PROBE Branch1',true),(branch2,c,'ERP-SALES-NUMBER-PROBE Branch2',true);
 INSERT INTO public.erp_branch_scopes(cafe_id,user_id,branch_id,revision) VALUES(c,actor,branch,1);
 INSERT INTO public.erp_branch_records(cafe_id,table_name,record_id,branch_id) VALUES(c,'bf_quotes',shared_id,branch2),(c,'bf_credit_notes',shared_id,branch2);
 PERFORM pg_temp.assert(NOT(public.brand_finance_quotes(c,shared_id)?'displayNumber'),'display does not expose other-branch quote number');
 PERFORM pg_temp.assert(NOT(public.brand_finance_credit_notes(c,shared_id)?'displayNumber'),'display does not expose other-branch credit number');
 PERFORM pg_temp.assert((public.brand_finance_credit_notes(c,NULL,'{"query":"CN-007"}')->>'total')::integer=0,'display search does not reveal other-branch credit');
 PERFORM pg_temp.assert(jsonb_array_length(public.erp_work_order_targets(c,'quotation','Q-007'))=0,'actual linked quote search hides other branch');
 DELETE FROM public.erp_branch_scopes WHERE cafe_id=c AND user_id=actor;
 PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);denied:=false;BEGIN PERFORM public.brand_finance_quotes(c,shared_id);EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'unauthorized quote reader denied');
 denied:=false;BEGIN PERFORM public.brand_finance_credit_notes(c,shared_id);EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'unauthorized credit reader denied');
 denied:=false;BEGIN PERFORM public.erp_system_numbering(c,'save',cfg,gen_random_uuid());EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'unauthorized settings save denied');
 PERFORM pg_temp.assert(NOT has_function_privilege('authenticated','brand_finance_private.quote_record(public.bf_quotes)','EXECUTE') AND NOT has_function_privilege('anon','brand_finance_private.credit_note_record(public.bf_credit_notes,boolean)','EXECUTE'),'private renderers not public number oracles');
 PERFORM pg_temp.assert(NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=c AND note LIKE 'ERP-SALES-NUMBER-PROBE%'),'numbering creates no financial postings');
END$$;
SELECT count(*) count,jsonb_agg(jsonb_build_object('name',name,'passed',passed)) checks FROM sales_number_checks;
